  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const src = ss.getSheetByName(SOURCE_SHEET);
  if (!src) throw new Error('Source sheet not found: ' + SOURCE_SHEET);

  const rng = src.getRange(SOURCE_RANGE);
  const values = rng.getValues();
  const firstRow = rng.getRow();

