  // 2) Group by normalized email (blank email = its own group).
  const groups = new Map();
  records.forEach(r => {
    const email = String(r.vals[EMAIL]).trim().toLowerCase();
    const key = email || ('__row' + r.row);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(r);
  });

  // 3) Merge each group.
  const output = [];
  groups.forEach(group => {
    // Newest first; on a timestamp tie, the lower sheet row (higher row number) first.
    group.sort((a, b) => {
      const ta = a.time === null ? -Infinity : a.time;
      const tb = b.time === null ? -Infinity : b.time;
      return tb !== ta ? tb - ta : b.row - a.row;
    });

    const keeper = group[0];
    const merged = keeper.vals.slice();
    merged[TS] = keeper.time === null ? keeper.vals[TS] : new Date(keeper.time);

    // Fill blanks on the keeper from the next-newest rows.
    for (let f = 1; f < FIELDS.length; f++) {
      if (isBlank(merged[f])) {
        const donor = group.find(r => !isBlank(r.vals[f]));
        if (donor) merged[f] = donor.vals[f];
      }
    }

    // Conflicts: more than one distinct non-blank (normalized) value in a field.
    const conflicts = [];
    for (let f = 1; f < FIELDS.length; f++) {
