      );
      if (distinct.size > 1) conflicts.push(FIELDS[f]);
    }
    if (group.some(r => r.time === null)) conflicts.push('Timestamp (unparsed)');

    output.push({ row: keeper.row, data: merged.concat(conflicts.join(', ')) });
  });

  // 4) Keep the original sheet order (by keeper row).
  output.sort((a, b) => a.row - b.row);
  const rows = output.map(o => o.data);

